import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void layernorm_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ Gamma,
    const T* __restrict__ Beta,
    int64_t M, int64_t N, float eps)
{
    int64_t m = blockIdx.x;

    // CuTe tensors for this row of X/Y and the full Gamma/Beta vectors
    auto gX = make_tensor(make_gmem_ptr(X + m * N), make_shape(N), make_stride(Int<1>{}));
    auto gY = make_tensor(make_gmem_ptr(Y + m * N), make_shape(N), make_stride(Int<1>{}));
    auto gGamma = make_tensor(make_gmem_ptr(Gamma), make_shape(N), make_stride(Int<1>{}));
    auto gBeta  = make_tensor(make_gmem_ptr(Beta),  make_shape(N), make_stride(Int<1>{}));

    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;

    double sum = 0.0;
    for (int64_t i = tid; i < N; i += nthreads) {
        sum += static_cast<double>(gX(i));
    }
    // Warp-level reduction (pass 1: mean)
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }
    __shared__ double s_sum[32];
    __shared__ double s_sumsq[32];
    int warp_id = tid / 32;
    int lane_id = tid % 32;
    if (lane_id == 0) {
        s_sum[warp_id] = sum;
    }
    __syncthreads();
    int num_warps = (nthreads + 31) / 32;
    if (warp_id == 0) {
        sum = (lane_id < num_warps) ? s_sum[lane_id] : 0.0;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        if (lane_id == 0) {
            s_sum[0] = sum;
        }
    }
    __syncthreads();
    float mean = (float)(s_sum[0] / (double)N);
    __syncthreads();
    // Pass 2: variance computed from centered values (numerically stable)
    double sumsq = 0.0;
    for (int64_t i = tid; i < N; i += nthreads) {
        float d = static_cast<float>(gX(i)) - mean;
        sumsq += static_cast<double>(d) * static_cast<double>(d);
    }
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sumsq += __shfl_down_sync(0xffffffff, sumsq, offset);
    }
    if (lane_id == 0) {
        s_sumsq[warp_id] = sumsq;
    }
    __syncthreads();
    if (warp_id == 0) {
        sumsq = (lane_id < num_warps) ? s_sumsq[lane_id] : 0.0;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sumsq += __shfl_down_sync(0xffffffff, sumsq, offset);
        }
        if (lane_id == 0) {
            s_sumsq[0] = sumsq;
        }
    }
    __syncthreads();
    float var = (float)(s_sumsq[0] / (double)N);
    if (var < 0.f) var = 0.f;
    float invstd = rsqrtf(var + eps);

    for (int64_t i = tid; i < N; i += nthreads) {
        float v = static_cast<float>(gX(i));
        float norm = (v - mean) * invstd;
        float g = static_cast<float>(gGamma(i));
        float b = static_cast<float>(gBeta(i));
        gY(i) = static_cast<T>(norm * g + b);
    }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(gamma.is_cuda() && beta.is_cuda(), "gamma/beta must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(gamma.scalar_type() == at::kFloat, "gamma must be float32");
    TORCH_CHECK(beta.scalar_type() == at::kFloat, "beta must be float32");

    auto x_c = x.contiguous();
    auto gamma_c = gamma.contiguous();
    auto beta_c = beta.contiguous();

    int64_t normalized_numel = gamma_c.numel();
    TORCH_CHECK(beta_c.numel() == normalized_numel, "gamma and beta must have same numel");

    int64_t total = x_c.numel();
    TORCH_CHECK(total % normalized_numel == 0, "x size must be divisible by normalized_shape numel");

    int64_t M = total / normalized_numel;
    int64_t N = normalized_numel;

    auto y = torch::empty_like(x_c);

    int threads = 512;
    if (N < 512) {
        // pick a smaller power-of-two block if N is small
        threads = 32;
        while (threads < N && threads < 512) threads *= 2;
    }

    dim3 block(threads);
    dim3 grid((unsigned)M);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    layernorm_kernel<float><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        gamma_c.data_ptr<float>(),
        beta_c.data_ptr<float>(),
        M, N, (float)eps
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single fused custom CUDA kernel using CuTe
    for tensor addressing. Computes mean/variance over the trailing `normalized_shape`
    dimensions per leading-batch element, then applies the affine transform.
    """
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = float(eps)

        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))

        self._ext = layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight,
            self.bias,
            self.eps,
        )

